        else if (abs >= BitsInByte * BytesInMegabyte) { value = Megabytes; symbol = MegabyteSymbol; }
        else if (abs >= BitsInByte * BytesInKilobyte) { value = Kilobytes; symbol = KilobyteSymbol; }
        else if (abs >= BitsInByte) { value = Bytes; symbol = ByteSymbol; }
        else { value = _bits; symbol = BitSymbol; }
    }

